package samples

import (
	"context"
	"testing"
	"time"

	. "github.com/smartystreets/goconvey/convey"
	"zhongkui.com/zhongkui/internal/models/network"
	_ "zhongkui.com/zhongkui/internal/network/detectors"
	"zhongkui.com/zhongkui/internal/network/tcp"
	"zhongkui.com/zhongkui/internal/pkg/errgroupx"
	"zhongkui.com/zhongkui/internal/pkg/logging"
)

var (
	httpChunkedGzipRequestRaw []byte = []byte(`GET / HTTP/1.1
Host: www.wireshark.org:8080
User-Agent: curl/7.46.0
Accept: */*
Connection: close
Accept-Encoding: chunked, gzip

`)
	httpChunkedGzipResponseRaw []byte = append([]byte(`HTTP/1.1 200 OK
Server: cloudflare-nginx
Date: Wed, 06 Jan 2016 20:42:10 GMT
Content-Type: text/html
Transfer-Encoding: chunked
Connection: close
Set-Cookie: __cfduid=d8d37b52eaa3137bdfd7fd67a4ffc8a7a1452112929; expires=Thu, 05-Jan-17 20:42:09 GMT; path=/; domain=.wireshark.org; HttpOnly
X-Frame-Options: SAMEORIGIN
Strict-Transport-Security: max-age=31536000;
X-Slogan: It's a great product with a great story to tell. I'm pumped!
X-Mod-Pagespeed: 1.9.32.11-7550
Vary: Accept-Encoding
Cache-control: max-age=0, no-cache, no-store
X-Slogan: Go deep.
CF-RAY: 260a3f709d7b0761-AMS
Content-Encoding: gzip

`),
		base64Decode(``)...,
	)
)

func TestHttpChunkedGzipCapFile(t *testing.T) {
	Convey("Test http chunked gzip cap file", t, func() {
		Convey("Should get http application", func(c C) {
			srcChan := make(chan *network.PacketIPv4TCP, 100)
			dstChan := make(chan any, 100)
			wg, ctx := errgroupx.WithContext(context.Background())
			logger, err := logging.NewDefaultLogger()
			c.So(err, ShouldBeNil)
			wg.Go(func() error {
				defer close(srcChan)
				return extractPackets(ctx, "http_chunked_gzip.cap", srcChan)
			})
			wg.Go(func() error {
				router := tcp.NewRouter[*network.PacketIPv4TCP](100, 100, time.Second)
				return router.Run(ctx, logger, srcChan, dstChan)
			})
			err = wg.Wait()
			c.So(err, ShouldBeNil)
			c.So(len(dstChan), ShouldEqual, 1)
			app := (<-dstChan).(*network.HttpTransport)
			compareHttpTransport(c, app, httpChunkedGzipRequestRaw, httpChunkedGzipResponseRaw)
			close(dstChan)
		})
	})
}
